INSERT INTO `admin` (`admin_id`, `real_name`, `account`, `password`, `phone`, `status`, `create_time`, `update_time`) VALUES (1, '超级管理员', 'admin', '$2a$10$sebsIPmyyx3oGxRIF3P3xew7xNR82LBUkFJpjZBOvkxcmeYfarJg6', '13800138000', 1, NOW(), NOW());
INSERT INTO `attraction` VALUES ('LS-001', '灵山大照壁', '地标、拍照', '景区入口处，面朝太湖，背靠景区核心区域，是进入灵山胜境的第一道视觉屏障与景观节点。', '打卡合影，拍摄湖光壁影同框美景；细细解读诗刻文化，感受赵朴初先生的书法魅力与禅意情怀；作为景区首处景观，适合定格入园第一帧画面。', '长39.8m，高7m，采用优质青石雕刻而成，被誉为“华夏第一壁”，整体造型恢弘大气，细节雕刻精美。', '景区标志性门户、文化序章，承担迎宾、文化展示功能，为游客开启禅意之旅的序幕。', '赵朴初先生亲笔题写鎏金“灵山胜境”四字，彰显景区佛教文化定位；背面《小灵山》诗刻，将无锡小灵山与印度灵鹫山相媲美，奠定整个景区的佛教文化基调，传递禅意人文底蕴。', '照壁采用优质青石精心雕刻，表面打磨光滑，纹理细腻，正面鎏金大字由赵朴初先生题写，笔力遒劲，鎏金工艺让字体在阳光下熠熠生辉。北立面刻有赵老诗作《小灵山》，诗中对比印度灵鹫山与中国小灵山，彰显中华佛教文化的自信与底蕴。照壁两侧与碧波荡漾的太湖交相辉映，构成“湖光山色共一楼”的壮美景观，成为景区入口处最具代表性的打卡景观。', '全天开放，无时间限制，适合各类时段入园游客观赏、打卡，不受景区内部演艺时间影响。', '进入景区首处打卡点，如愿火车站装置为小众取景框，搭配照壁与太湖背景，可拍出独具特色的禅意照片。', 0);
INSERT INTO `attraction` VALUES ('LS-002', '五明桥', '文化、轻松', '景区入口处，面朝太湖，背靠景区核心区域，是进入灵山胜境的第一道视觉屏障与景观节点。', '漫步过桥，在行走中体悟五明智慧的内涵；拍摄石桥与香水海的倒影同框美景，感受水与建筑的禅意融合；桥面宽阔平坦，适合驻足观赏周边景致。', '5座石拱桥并列排布，间距均匀，桥身采用汉白玉雕刻而成，桥面与桥栏均刻有精美佛教图案，造型规整大气。', '佛教智慧象征、通行步道，既是连接不同区域的交通载体，也是传递佛教智慧、营造禅意氛围的重要景观。', '代表佛教中的五种核心智慧，分别为声明(语言学)、因明(逻辑学)、内明(哲学)、医方明(医学)、工巧明(工艺学)，寓意过桥即能开启智慧、走向觉悟。', '五座石桥形态规整、气势统一，桥面平整宽阔，桥栏由优质汉白玉打造，质地细腻，上面雕刻着莲花、飞天、神兽等精美佛教图案，线条流畅、栩栩如生。石桥倒映在香水海的碧波之中，如五条洁白玉带横卧水面，意境悠远。佛教认为人类文明的核心可归为五大类，漫步过桥的过程，便是寓意着逐步获得五种智慧、开启禅意觉悟之路的过程。', '全天开放，无时间限制，免费向所有游客开放通行，不受天气及景区演艺活动影响。', '无门票，免费通行，是连接入口与核心景区的必经之路，也是游客感受佛教智慧文化的首个核心节点。', 0);
INSERT INTO `attraction` VALUES ('LS-003', '佛足坛', '祈福、佛教文化', '五明桥北侧，菩提大道起点，处于景区中轴线之上，与后方的五智门、灵山大佛遥相呼应，是核心朝圣节点。', '瞻仰佛足，亲手触摸足心吉祥图案，寄托祈福心愿；细细解读32种吉祥瑞相的寓意，了解佛教文化内涵；与佛足坛合影，定格朝圣瞬间。', '巨型佛足印一对，左右对称摆放，每只足印长1.2m，宽0.6m，采用整块青铜铸造而成，表面经过特殊防腐处理，色泽温润。', '祈福朝圣、佛教象征，是佛教徒朝拜的核心点位，也是游客感受佛教圣迹、寄托祈福心愿的重要景观。', '复刻佛祖释迦牟尼真身脚印，足心刻有千辐轮相、宝瓶鱼纹等32种吉祥图案，每种图案都蕴含着独特的佛教寓意，象征“佛足所至，佛光普照”，代表佛的福德与智慧圆满。', '佛足坛由整块青铜精心铸造，采用古法铸造工艺，表面光滑细腻，完美呈现出佛祖脚印的32种吉祥瑞相，每一处纹路都清晰可辨，是佛教徒千百年供奉的神圣遗迹。相传佛祖涅槃前，特意留下双足印并嘱托弟子：“佛足所至，即为佛地”，这对佛足也因此被称为“两足尊”，是佛教文化中“福德圆满、智慧无量”的象征。', '全天开放，无时间限制，适合游客随时驻足瞻仰、祈福，周边设有休息区域，方便游客停留观赏。', '佛教朝圣核心节点，与遥相呼应，形成“圣迹在前、殿堂在后”的庄严格局，是进入核心景区前的重要朝圣环节。', 0);
INSERT INTO `attraction` VALUES ('LS-004', '五智门', '地标、拍照、灯光', '佛足坛北侧，核心景区入口处，矗立在景区中轴线上，是区分景区外围区域与核心朝圣区域的重要标志。', '穿门祈福，感受佛教建筑的恢弘气势；拍摄牌坊全景，搭配蓝天绿树背景，定格庄严肃穆的禅意画面；解读门柱经文与门楣图案，深入了解佛教六度智慧。', '高16.8m，宽35m，为五门六柱石牌坊造型，整体采用优质汉白玉雕刻而成，牌坊顶部雕刻精美，气势恢宏壮观。', '核心景区门户、智慧象征，承担着划分景区区域、传递佛教智慧、营造庄严肃穆氛围的核心功能。', '五门分别象征五方五佛，代表佛教的全域覆盖与普度众生；六柱代表佛教“六度波罗蜜”，即布施、持戒、忍辱、精进、禅定、般若，门柱上刻有对应的佛教经文，字字珠玑，传递佛教修行的核心智慧。', '五智门由优质汉白玉精雕细琢而成，雕刻工艺精湛绝伦，门柱上雕刻着佛教六度智慧的相关经文，字体工整、苍劲有力；门楣处饰有飞天、神兽、莲花等吉祥图案，造型栩栩如生，尽显佛教艺术的庄严与精美。整座牌坊气势恢宏，矗立在景区中轴线上，与后方的灵山大佛在同一直线上，穿过这道门，便正式从“凡俗之境”踏入“禅意圣地”，开启核心朝圣之旅。', '全天开放，无时间限制，无论白天黑夜，都能感受其庄严气势，夜间有灯光点缀，更具氛围感。', '进入核心区的标志，与灵山大佛在同一条中轴线上，是景区中轴线景观的重要组成部分，也是游客打卡核心景观的必经之地。', 0);
INSERT INTO `attraction` VALUES ('LS-005', '菩提大道', '自然、慢游', '五智门北侧，直通九龙灌浴广场，贯穿景区中轴线核心路段，两侧绿植繁茂，是连接五智门与核心景观的重要步道。', '漫步林荫拱廊，感受禅意清幽，聆听菩提叶作响的自然之声；春季菩提花开时，可观赏洁白的菩提花，定格绝美瞬间；还可捡拾掉落的菩提叶，制作特色书签作为纪念。', '长约250m，宽约10m，路面采用防滑耐磨的特殊材料铺设，四季常绿；两侧对称种植近百棵从印度引进的正宗菩提树，枝繁叶茂。', '朝圣步道、禅意景观，既是游客前往核心景观的通行通道，也是营造禅意氛围、引导游客感悟佛法的重要场所。', '以菩提树为核心景观载体，象征佛陀在菩提树下悟道成佛的艰辛历程，营造清净悠远的禅境，引导信众与游客从凡俗喧嚣走向内心觉悟。', '菩提大道两侧的菩提树均为从印度引进的正宗树种，树形挺拔、枝叶繁茂，树枝交错缠绕，形成天然的禅意拱廊，遮挡烈日的同时，也增添了静谧的氛围。地面采用特殊防滑材料铺设，平整宽阔，四季保持常绿，行走其上倍感舒适。漫步其间，微风拂过，菩提叶沙沙作响，宛如佛音萦绕耳畔，让人瞬间忘却尘世喧嚣，身心归于清净，为前往九龙灌浴的朝圣之旅做好心境铺垫。', '全天开放，无时间限制，四季景致各异，春季赏菩提花、夏季避酷暑、秋季观落叶、冬季赏绿意，适合各类时段游览。', '直通九龙灌浴广场，是前往核心景观的必经之路，春季菩提花开时景致绝美，是景区内最具禅意的步道之一。', 0);
INSERT INTO `attraction` VALUES ('LS-006', '九龙灌浴', '表演、互动、热门、体验', '菩提大道北端，景区中轴线核心位置，是灵山胜境最具标志性的动态景观，周边设有开阔的观赏广场。', '观赏动态喷泉表演，感受“花开见佛”的震撼场景；表演结束后，可在广场两侧接取龙头流出的“圣水”，寓意祈福安康、沾取佛诞祥瑞之气；拍摄表演全过程，定格绝美瞬间。', '总高27.2m，核心为鎏金太子佛，高7.2m，重12吨，整体耗铜量达180吨；太子佛周围环绕9组72只凤凰雕塑，搭配九条栩栩如生的飞龙，造型精美壮观。', '动态景观、佛教诞生故事演绎，核心展示释迦牟尼诞生的祥瑞场景，兼具观赏、科普与祈福功能。', '依据《本行经》中释迦牟尼诞生的传说精心打造，生动再现“花开见佛，九龙沐浴”的祥瑞景象，传递佛教“诞生即祥瑞”的核心文化内涵。', '大型音乐动态群雕由莲花铜雕、九条飞龙、八名供养人等核心元素组成，莲花底座由四个大力士造型雕塑托起，底部是圆形大理石水池，池水清澈见底，周围环绕九条形态各异的飞龙和八名供养人雕塑。太子佛通体鎏金，色泽鲜亮，在专属背景音乐《佛之诞》响起时，莲花铜雕会缓缓绽放，太子佛从莲花中缓缓升起并自转一周，九条飞龙同时喷出水柱，高达数十米，精准沐浴在太子佛身上，整个场景震撼人心，完美还原佛陀诞生的祥瑞瞬间。', '平日演出时间为10:00、11:30、13:30、15:00；周末及节假日增加演出场次（具体以景区广播通知为准），每场演出时长约15分钟，建议提前10分钟到场占位。', '景区标志性动态景观，是游客必看的核心景点之一，表演结束后可领取“圣水”，寄托祈福心愿，周边设有休息区和打卡点。', 1);
INSERT INTO `attraction` VALUES ('LS-007', '降魔浮雕', '文化、佛教文化', '九龙灌浴北侧，阿育王柱前方，紧贴景区中轴线，两侧设有观赏步道，是连接九龙灌浴与阿育王柱的重要景观节点。', '观赏精湛的浮雕艺术，感受佛教雕刻的魅力；聆听佛陀降魔成道的故事，深入理解佛教禅理；寻找浮雕中的细节，分辨不同人物的身份与神态，感受艺术与文化的融合。', '长26m，高4.6m的巨型石雕，采用整块优质花岗岩雕刻而成，浮雕厚度均匀，雕刻深度适中，立体感极强。', '佛教故事展示、艺术景观，核心用于科普佛教文化，展示佛陀成道的艰辛历程，兼具艺术观赏与文化传播功能。', '生动再现佛陀在菩提树下静坐修行，战胜魔王波旬各种诱惑与威胁，最终觉悟成佛的艰辛历程，传递“坚守本心、终能成道”的禅理。', '浮雕采用高浮雕与浅浮雕相结合的精湛手法，分层刻画场景，层次感十足。浮雕中央，佛陀端坐于菩提树下，神情坚定、目光如炬，尽显佛法的无畏与庄严；两侧，魔王波旬率领魔女、魔兵，以美色、财富、武力等各种方式诱惑、威胁佛陀，魔女身姿妖娆、魔兵面目狰狞，与佛陀的沉稳无畏形成鲜明对比。雕刻细节极为丰富，人物的表情、动作、服饰都栩栩如生，甚至发丝、衣纹都清晰可辨，是佛教艺术中的珍品，极具观赏与研究价值。', '全天开放，无时间限制，浮雕前设有防护设施，方便游客观赏、拍照，不受天气影响。', '佛教文化核心科普点，雕刻工艺精湛，是了解佛陀“八相成道”关键环节的重要景观，适合亲子、文化爱好者细细品味。', 0);
INSERT INTO `attraction` VALUES ('LS-008', '阿育王柱', '地标、拍照', '降魔浮雕北侧，祥符禅寺正前方，矗立在景区中轴线之上，与灵山大佛、五智门形成一条直线，庄严肃穆。', '瞻仰巨型石柱，感受其威严气势；拍摄四狮柱头的精美细节，了解其象征意义；聆听阿育王弘扬佛法的故事，深入了解佛教东传的历史。', '通高16.9m，直径1.8m，总重量达180吨，采用整块优质花岗岩一次性雕刻而成，柱头雕刻四头朝向不同方向的狮子，造型威严。', '佛教文化象征、地标景观，核心用于传递佛教和平精神，纪念佛法东传的历史，兼具地标打卡与文化科普功能。', '复刻古印度阿育王石柱的造型，柱头四头狮子分别朝向东南西北四方，象征佛法向世界各地传播，彰显佛教“和平、包容、普度”的核心精神。', '阿育王柱由整块优质花岗岩精心雕刻而成，雕刻工艺精湛，柱身表面打磨光滑，刻有“阿育王柱”四个大字及相关梵文经文，字体工整、苍劲有力，历经多年风雨依旧清晰可辨。柱头雕刻的四头狮子，形态威严、栩栩如生，每头狮子的表情、姿态都各不相同，尽显王者风范。阿育王是古印度历史上最著名的弘扬佛法的国王，他统一印度后放下屠刀、笃信佛教，将佛法传播至世界各地，这根石柱也成为佛教从印度传入中国的重要历史象征，连接着中印两国的佛教文化渊源。', '全天开放，无时间限制，石柱周边设有开阔的观赏区域，方便游客观赏、拍照，不受天气及景区演艺活动影响。', '景区标志性石质地标，与灵山大佛、五智门形成呼应，构成景区中轴线的核心景观序列，是佛教文化传播的重要载体。', 0);
INSERT INTO `attraction` VALUES ('LS-009', '百子戏弥勒', '亲子、趣味', '阿育王柱与祥符禅寺之间，处于景区中轴线旁侧，周边设有休息座椅，是游客驻足祈福、拍照的热门点位。', '触摸弥勒佛的肚皮，寓意“摸弥勒肚皮，享一生福气”，寄托顺遂安康的心愿；寻找百名孩童的不同姿态，感受民间艺术的魅力；亲子互动拍照，定格温馨瞬间，祈求家庭和睦、子孙满堂。', '高3m，宽7.8m，总重量达9吨的青铜群雕，弥勒佛呈卧姿，袒胸露腹、笑容满面，身上塑有百名嬉戏的孩童，形态各异、生动活泼。', '祈福景观、民俗文化展示，核心用于传递欢喜、包容的理念，满足游客祈福心愿，兼具民俗体验与亲子互动功能。', '弥勒佛是佛教中的未来佛，象征着“欢喜、包容、慈悲”，百子环绕在弥勒佛身边，寓意“多子多福、家庭和睦、子孙满堂”，完美融合了佛教的“慈悲喜舍”与民间的祈福愿望。', '青铜群雕采用优质青铜铸造，经过特殊防腐处理，色泽温润，造型精美。群雕中，弥勒佛呈舒适的卧姿，袒胸露腹，嘴角上扬，笑容憨厚可掬，尽显“大肚能容天下难容之事”的包容气度。身上塑有的百名孩童，形态各异、生动活泼，有的攀爬在弥勒佛身上，有的在其身边嬉戏打闹，有的挠弥勒佛的肚皮，每个孩童的表情、动作都独具特色，充满童趣，展现出浓郁的民间艺术灵动之美，深受游客尤其是亲子家庭的喜爱。', '全天开放，无时间限制，群雕前无遮挡，方便游客观赏、触摸、拍照，周边设有休息区域，适合驻足停留。', '民俗祈福热门点位，亲子互动拍照的绝佳去处，群雕细节丰富，兼具佛教文化与民俗风情，是景区内最具亲和力的景观之一。', 0);
INSERT INTO `attraction` VALUES ('LS-010', '祥符禅寺', '祈福、佛教文化、热门、表演', '灵山胜境中轴核心，灵山大佛基座之下，四周绿树环绕，环境清幽，是景区内历史最悠久的人文景观。', '礼佛祈福，虔诚朝拜，寄托美好心愿；聆听祥符禅钟的浑厚钟声，感受禅意悠远；观赏唐代古建与千年历史遗迹，秋季可欣赏千年银杏的金黄景致，感受古刹的静谧与庄严。', '唐代古刹，占地约30亩，整体采用仿唐重檐歇山式建筑风格，布局完整，包含弥勒殿、大雄宝殿、钟楼、鼓楼，寺内还有六角井、八角井、白莲池、千年古银杏等珍贵历史遗迹；钟楼内悬挂重12.8吨的“祥符禅钟”。', '宗教活动开展、千年古刹瞻仰，核心用于佛教信徒礼佛祈福，同时展示江南禅宗文化，兼具宗教体验、历史科普与人文观赏功能。', '始建于唐贞观年间，由玄奘法师的弟子窥基大师开坛讲经，北宋年间正式更名为“祥符禅寺”，历经千年风雨洗礼，香火绵延不绝，是江南地区重要的千年禅宗祖庭，也是佛教文化传承与传播的重要场所。', '祥符禅寺布局严谨、错落有致，整体采用仿唐重檐歇山式建筑风格，红墙黛瓦、飞檐翘角，尽显唐代古建的庄严与恢弘。大雄宝殿内供奉着释迦牟尼佛及迦叶、阿难两大弟子，佛像庄严慈祥，香火鼎盛，是信徒礼佛的核心场所；钟楼内悬挂着一口重12.8吨的“祥符禅钟”，钟声浑厚洪亮，响彻整个灵山山谷。寺内的六角井是唐代名泉，曾被茶圣陆羽品鉴，列为江南名泉之一，井水清澈甘甜；千年古银杏树龄超过千年，枝繁叶茂，见证了寺院的兴衰变迁与灵山的千年发展，秋季金黄的树叶铺满寺院，意境绝美。', '全天开放，宗教活动正常开展；钟楼定时有钟声表演，具体时间以景区广播通知为准，寺内禁止大声喧哗，需保持庄严肃穆。', '景区历史文化根基，始建于唐贞观年间，是江南千年禅宗祖庭，承载着丰富的佛教文化与历史底蕴，是了解灵山历史的重要场所。', 1);
INSERT INTO `attraction` VALUES ('LS-011', '灵山大佛', '地标、祈福、视觉震撼、热门', '祥符禅寺北侧，秦履峰南侧，矗立在景区最高处，是整个灵山胜境的核心地标，可俯瞰整个景区及太湖风光。', NULL, '佛像高88m（主体高度79m+莲花瓣高度9m），含台基总高101.5m，耗铜量达725吨，由2000块铸铜面板拼接而成，', '', NULL, NULL, NULL, NULL, 1);
INSERT INTO `attraction` VALUES ('LS-012', '佛教文化博览馆', '文化、安静、沉浸式', '灵山大佛座基内，共三层结构，每层功能不同，布局合理，是灵山博物馆的核心展区，地理位置便利，方便游客参观，与佛脚平台入口相邻。', '体验智能导览，深入了解佛教历史与四大名山文化；在二层互动区参与佛法东传知识问答，解锁趣味科普内容；在三层万佛殿打卡祈福，拍摄金碧辉煌的佛像阵列；观赏馆内珍藏的佛教文物复刻品，感受佛教艺术的传承。', '总建筑面积达10000㎡，为三层框架结构，层高均超4米，空间开阔通透；一层展示五方五佛与佛教四大名山文化，二层介绍世界佛教发展史，三层为万佛殿；馆内配备智能导览屏、沉浸式投影、文物复刻展柜等现代化展陈设施。', '佛教文化展示、科普教育，核心用于展示佛教历史、文化内涵与艺术成果，兼具科普、观赏与互动体验功能，免费向游客开放，是灵山胜境的文化科普核心阵地。', '系统展示五方五佛、中国佛教四大名山的文化特色，梳理世界佛教的发展脉络，三层万佛殿内的9999尊小佛像与室外灵山大佛合称为“万佛朝宗”，彰显佛教的庄严与恢弘。博览馆的展陈设计兼顾专业性与通俗性，让不同年龄段、不同文化背景的游客都能读懂佛教文化。', '佛教文化博览馆设于灵山大佛三层座基内，是灵山博物馆的核心组成部分，整体装修融合佛教元素与现代设计理念，恢弘大气且充满禅意。一层展厅以“五方五佛”与中国佛教四大名山为核心，陈列着数十尊佛像复刻品、历代佛教法器、名山文化卷轴，搭配实景沙盘，直观展现五台山、普陀山等名山的地理格局与宗教地位；二层展厅以时间为轴线，通过图文展板、沉浸式投影、文物复刻，详细介绍世界佛教的发展历程，从释迦牟尼佛祖成道，到佛法在印度、中国、东南亚等地的传播，脉络清晰，其中“佛法东传”互动区可让游客通过触屏了解关键历史节点；三层为万佛殿，殿内采用鎏金装饰与暖光照明，9999尊灵山大佛真身小佛像整齐排布于殿内四周与穹顶，每尊小佛均按1:100比例复刻大佛造型，工艺精细，与室外的灵山大佛形成“上下呼应、万佛朝宗”的震撼格局，殿中央还设有祈福台，供游客静心祈愿。', '随灵山大佛开放时间同步运营（8:00-17:00），冬季闭馆时间提前至16:30；馆内设有免费讲解服务，讲解时段为9:30、11:00、14:30、16:00，无需预约，在一层入口集合即可；沉浸式投影体验每30分钟一场，循环播放。', '灵山博物馆核心展区，免费参观，馆内禁止触摸文物展柜与佛像，禁止使用闪光灯拍照；三层万佛殿内可免费领取祈福卡，写下心愿后悬挂于指定祈福区。', 0);
INSERT INTO `attraction` VALUES ('LS-013', '灵山梵宫', '视觉震撼、灯光、沉浸式、热门、体验、表演', '灵山胜境西侧，香水海之畔，与五印坛城隔湖相望，背靠秦履峰余脉，地势开阔，是景区内建筑规模最大、艺术价值最高的单体建筑。', '观赏东阳木雕、琉璃、油画等非遗艺术瑰宝，感受传统工艺的精湛；在中庭仰望星空穹顶，体验“置身佛国”的奇幻意境；观看《灵山吉祥颂》大型演出，沉浸式感受佛陀成道的故事；打卡梵宫建筑全景，拍摄“莲花圣塔”与香水海的同框美景。', '建筑面积达72000㎡，最高处66.5米，整体呈“莲花环抱”之势，拥有五座错落分布的莲花圣塔；建筑主体采用钢混结构，外立面融合石材雕刻与玻璃幕墙，内部汇集东阳木雕、琉璃、油画、景泰蓝、玉雕、漆画等多种传统工艺；圣坛为曼陀罗形态，可容纳2000人同时观演，荣获中国建筑工程最高奖——鲁班奖。', '佛教艺术殿堂、国际佛事活动举办地，核心用于展示佛教艺术瑰宝，举办世界佛教论坛等高端佛事活动，同时为游客提供艺术观赏、演艺体验服务。', '融合中国传统佛教建筑、敦煌石窟艺术与现代建筑设计理念，以“莲花藏世界”为设计核心，五座莲花圣塔象征五方五佛，曼陀罗形态圣坛寓意宇宙圆满，是佛教文化与传统艺术完美融合的典范，也是第二、四届世界佛教论坛的永久会址。融合中国传统佛教建筑、敦煌石窟艺术与现代建筑设计理念，以“莲花藏世界”为设计核心，五座莲花圣塔象征五方五佛，曼陀罗形态圣坛寓意宇宙圆满，是佛教文化与传统艺术完美融合的典范，也是第二、四届世界佛教论坛的永久会址。', '灵山梵宫于2008年建成，凭借其极致的艺术价值与恢弘的建筑规模，被誉为“东方卢浮宫”。建筑外立面以米黄色石材为基底，雕刻着莲花、飞天、经文等佛教元素，五座莲花圣塔矗立其上，塔刹采用鎏金工艺，在阳光下熠熠生辉。内部空间更是堪称“艺术殿堂”，每一处细节都凝聚着非遗传承人的心血：廊厅两侧的12幅高12米、宽3米的“世界佛教传法图”油画，由多名油画家耗时数年创作，笔触细腻，色彩绚丽，完整再现了佛教在世界各地的传播历程；中庭28米高的星空穹顶，镶嵌着数万颗进口LED灯，可模拟日月星辰的流转变化，搭配穹顶下方的东阳木雕飞天，行走其间仿佛置身于宇宙苍穹与佛国仙境之中；梵宫核心的琉璃巨制《华藏世界》，宽8米、高10米，由160块彩色琉璃拼接而成，采用古法脱蜡铸造工艺，融入佛教“华藏世界”的核心意象，色彩斑斓，晶莹剔透，是目前世界上最大的琉璃艺术作品之一。此外，梵宫内的景泰蓝须弥灯、玉雕佛龛、漆画屏风等，均为非遗艺术精品，尽显中华传统工艺的魅力。', '9:00-17:00开放，冬季闭馆时间提前至16:30；《灵山吉祥颂》演出时间为10:35、11:30、14:00、16:00，每场时长约20分钟，凭景区大门票免费入场，建议提前30分钟到场排队占座；节假日会根据客流加演1-2场，具体以景区广播与官方小程序通知为准。', '被誉为“东方卢浮宫”，第二、四届世界佛教论坛举办地；梵宫内部分区域（如圣坛）禁止随意走动，需遵循工作人员指引；拍照时禁止使用闪光灯，以免损伤油画与琉璃作品。', 1);
INSERT INTO `attraction` VALUES ('LS-014', '五印坛城', '拍照、体验', '香水海中央的独立圆岛上，灵山梵宫南侧，通过景观栈道与梵宫相连，四面环水，环境清幽，藏式建筑风格与周边江南景观形成鲜明对比。', '体验藏传佛教文化，参观藏式建筑与唐卡展厅；顺时针转动转经筒，寄托祈福安康的心愿；登至五层顶层观景台，俯瞰香水海、灵山梵宫与灵山大佛的全景，感受“三水环抱、佛塔相映”的绝美意境；参与藏香制作体验，亲手制作属于自己的藏香。', '五层重檐楼宇，总高约30米，占地5000㎡，整体采用藏式碉楼建筑风格，白墙红边金顶，墙体采用花岗岩砌筑，屋顶覆盖鎏金铜瓦；四门分别安置马宝、孔雀、共命鸟、象宝四尊瑞兽雕塑，每尊瑞兽高2.5米，采用青铜铸造；内部设有主殿、展厅、转经筒长廊等区域，陈列着数百件藏传佛教文物。', '藏传佛教文化展示中心、禅意祈福场所，核心用于展示藏传佛教的历史、艺术与文化，为游客提供藏传佛教文化体验与祈福服务。', '“五印”代表五方五佛的五种手印（施无畏印、与愿印、说法印、禅定印、降魔印），坛城是藏传佛教中的“曼陀罗道场”，象征着宇宙的和谐、圆满与神圣；五印坛城的建造，体现了汉传佛教、藏传佛教的文化交融，彰显了佛教的包容性。', '五印坛城以西藏拉萨布达拉宫雪村大门为原型设计山门，门楣处雕刻着藏文经文与吉祥八宝图案，气势庄严。整座建筑白墙如练，红边勾勒出建筑轮廓，鎏金铜瓦打造的屋顶在阳光与湖水的映衬下，闪耀着金色光芒，四门的瑞兽雕塑造型生动，各有寓意：马宝象征吉祥如意，孔雀代表智慧光明，共命鸟寓意和睦友爱，象宝象征太平盛世。内部装饰延续了藏传佛教的华丽风格，墙体绘有彩色唐卡，内容涵盖藏传佛教的诸佛、菩萨、护法神等，采用天然矿物颜料绘制，历经百年仍色彩鲜艳；主殿内供奉着五方五佛的藏式造像，佛像由尼泊尔工匠手工雕刻，鎏金工艺精湛，神态庄严。转经筒长廊环绕主殿，摆放着108个纯铜转经筒，筒内装有藏文经文，游客可顺时针转动转经筒，寓意祈福消灾、积累功德。此外，馆内还设有藏传佛教文化展厅，陈列着唐卡、法器、藏香等珍贵文物，详细介绍藏传佛教的发展历程与文化特色。', '9:00-17:00开放，冬季闭馆时间提前至16:30；转经筒长廊全天开放，藏香制作体验需提前在景区小程序预约，体验时段为10:00、14:00，每场时长约40分钟，费用自理；内部展厅禁止触摸文物与佛像，禁止大声喧哗。', '藏传佛教文化核心区，有“小布达拉宫”之称；与灵山梵宫、曼飞龙塔共同构成佛教三大语系建筑群落；因位于湖心岛，雨天栈道可能湿滑，游览时需注意安全。', 0);
INSERT INTO `attraction` VALUES ('LS-015', '曼飞龙塔', '建筑、小众', '五印坛城北侧，香水海北岸的景观绿地上，与五印坛城隔岸相望，背靠灵山梵宫，处于佛教三大语系建筑群落的核心位置。', '拍照打卡，感受南传佛教建筑的异域美学；对比曼飞龙塔（南传）、灵山梵宫（汉传）、五印坛城（藏传）的建筑差异，了解佛教三大语系的文化特色；拍摄九塔组合全景，搭配香水海与五印坛城背景，定格绝美瞬间；解读塔身雕刻的图案与经文，深入了解南传佛教文化。', '主塔高16.9m，底部为直径10米的圆形须弥座，由一座主塔和八座高约8米的小塔组成九塔组合；塔身以白色花岗岩为主要材质，表面雕刻着精美的佛教浮雕与纹饰，塔刹采用鎏金铜质，呈锥形；整体为南传佛教干栏式建筑风格，兼具傣族建筑特色。', '南传佛教建筑展示、景观打卡地标，核心用于展示南传佛教的建筑美学与文化特色，丰富景区的佛教文化内涵，同时作为特色景观供游客观赏、拍照。', '复刻云南西双版纳景洪市的曼飞龙白塔，是南传佛教的标志性建筑之一；九塔组合象征着南传佛教的九种智慧，也代表着佛陀的九种功德；这座佛塔的建造，让汉传、藏传、南传三大语系佛教建筑齐聚灵山，彰显了佛教文化的多元性与包容性。', '曼飞龙塔又称“白塔”，是灵山胜境中代表南传佛教文化的核心建筑，完全复刻了云南西双版纳曼飞龙白塔的形制与工艺。主塔矗立在圆形须弥座中央，塔身呈葫芦状，自上而下逐渐收窄，塔刹高耸，鎏金装饰熠熠生辉；八座小塔环绕主塔分布，呈八角形排列，塔身造型与主塔相似，比例协调，形成“众星拱月”的格局。塔身表面的雕刻极为精美，采用浅浮雕工艺，刻有释迦牟尼佛成道图、阿罗汉像、莲花纹、卷草纹等南传佛教特色图案，线条流畅，造型生动，展现了傣族雕刻艺术的独特魅力。须弥座的侧面刻有傣文经文与吉祥图案，彰显了南传佛教的文化特色。白色的塔身与金色的塔刹在阳光的照耀下，与周边的绿水、绿树相映成趣，形成一道独具异域风情的景观。站在塔前，既能感受到南传佛教建筑的简洁庄严，也能体会到不同佛教文化交融的独特魅力。', '全天开放，无时间限制；塔身周边设有观景步道与休息座椅，方便游客观赏、拍照；因塔身采用花岗岩雕刻，表面光滑，雨天游览时需注意防滑。', '景区异域风格地标，与五印坛城、灵山梵宫形成佛教三大语系建筑群落；塔身雕刻细节丰富，适合文化爱好者与摄影爱好者细细品味；夜间有灯光亮化，塔刹与塔身轮廓会被点亮，夜景同样绝美。', 0);
INSERT INTO `attraction` VALUES ('LS-016', '无尽意斋', '休闲、文化', '祥符禅寺西北侧，灵山大佛左下方的山林间，毗邻景区的禅意休息区，环境清幽，远离景区主客流，是一处闹中取静的人文景观。', '参观赵朴初先生纪念馆，了解其生平事迹与对佛教文化的贡献；欣赏赵朴初先生的书法作品，感受其书法艺术的魅力；在天井的石桌石凳处静坐休憩，远离景区喧嚣，享受片刻的宁静；在禅意茶室免费品鉴禅茶，体验禅茶一味的意境；参与临时展厅的文化展览，丰富人文体验。', '占地600㎡，为典型的北京四合院风格建筑，坐北朝南，由正房、东西厢房、倒座房组成，围合形成天井；建筑采用青砖灰瓦、木质梁柱，门窗为传统雕花样式，复刻赵朴初先生北京故居的建筑格局与内饰风格；院内设有景观绿植、石桌石凳，建筑面积约400㎡。', '名人纪念馆、佛教文化展示、人文休憩场所，核心用于纪念赵朴初先生，展示其与灵山的渊源及对佛教文化的贡献，同时为游客提供一处静心休憩、感受人文禅意的场所。', '“无尽意”取自佛教经典《无尽意菩萨经》，象征着赵朴初先生对佛教文化传承、慈善事业发展的无尽初心与执着追求；无尽意斋作为赵朴初先生的纪念馆，是灵山胜境人文底蕴的重要载体，彰显了“佛教文化+人文精神”的融合。', '无尽意斋于2008年建成，完全以赵朴初先生北京西城区的故居为原型复刻建造，一砖一瓦、一草一木都力求还原故居的原貌。建筑为典型的北京四合院格局，青砖灰瓦古朴厚重，木质梁柱雕刻着简洁的吉祥图案，雕花门窗采用榫卯结构，尽显中式建筑的精巧。正房为纪念馆的核心展区，分为“生平事迹厅”“灵山渊源厅”“书法作品厅”三个部分：生平事迹厅通过图文展板、老照片、实物陈列，详细介绍赵朴初先生的一生，包括他投身佛教事业、参与慈善活动、推动中外文化交流的重要事迹；灵山渊源厅陈列着赵朴初先生与灵山胜境的往来书信、题字手稿、合影照片，展现了他从灵山胜境立项到建成开光，全程参与、悉心指导的深厚渊源；书法作品厅展出了赵朴初先生的数十幅书法真迹与复刻品，其书法兼具颜体的浑厚与柳体的挺拔，内容多为佛教经文、禅意诗句，笔力遒劲，意境悠远。东西厢房设有临时展厅与禅意茶室，临时展厅会定期举办佛教文化、书法艺术相关展览，禅意茶室提供免费的禅茶品鉴，游客可在此静坐品茗，感受宁静。天井内种植着海棠、石榴、翠竹等绿植，搭配石桌石凳，微风拂过，竹影婆娑，充满了中式庭院的禅意与雅致。', '9:00-17:00开放，冬季闭馆时间提前至16:30；禅茶品鉴全天免费提供，茶叶为景区自产的灵山禅茶，需自行取用；临时展厅的展览内容会定期更新，可通过景区小程序了解最新展览信息；馆内禁止触摸书法作品与实物陈列，禁止大声喧哗。', '景区人文文化重要节点，免费参观；因位于山林间，道路略有坡度，行动不便的游客可乘坐景区观光车前往（观光车费用自理）；正房的书法作品真迹为重点保护文物，禁止使用闪光灯拍照。', 0);
