INSERT INTO `knowledge_doc` VALUES (1, '门票与优惠政策', '成人票210元；半价票105元（6-18周岁、全日制本科及以下学生、60-69周岁老人）；免票（6周岁以下或1.4米以下儿童、70周岁以上老人、现役军人、残疾人）；网购联票225元（门票+观光车无限次）；观光车单独购票40元/人。', '服务信息', '门票', '2026-04-17 18:19:57', '2026-05-18 20:17:02');
INSERT INTO `knowledge_doc` VALUES (2, '最佳游览时间', '季节：春秋季3-5月、9-11月气候宜人；建议上午9点前入园避峰；下午可观赏太湖日落；九龙灌浴每日4-5场，《吉祥颂》演出时间10:35、11:30、14:00、16:00，时长20分钟。', '服务信息', '游览时间', '2026-04-17 18:19:57', '2026-05-29 21:22:35');
INSERT INTO `knowledge_doc` VALUES (3, '表演时间', '九龙灌浴每日4-5场表演；《吉祥颂》演出每日10:35、11:30、14:00、16:00（以景区公告为准），时长20分钟。', '服务信息', '表演时间', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
INSERT INTO `knowledge_doc` VALUES (4, '餐饮推荐', '梵宫素斋自助50元/位；素面套餐35元/位；灵山精舍素斋，环境优雅、菜品精致，适合深度体验。', '服务信息', '餐饮', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
INSERT INTO `knowledge_doc` VALUES (5, '住宿推荐', '景区内：灵山精舍禅意酒店，含素斋与早课体验；景区周边：马山镇酒店、民宿，价格区间广，满足不同预算。', '服务信息', '住宿', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
INSERT INTO `knowledge_doc` VALUES (6, '景区内交通', '观光车40元/人，无限次乘坐，适合体力有限、老人、儿童游客，串联核心景点。', '服务信息', '景区交通', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
INSERT INTO `knowledge_doc` VALUES (7, '游览注意事项', '穿着舒适运动鞋；夏季防晒、冬季保暖；携带相机、充电宝、雨具；景区提供导游300元起；佛教场所需文明安静，部分区域禁止拍照。', '服务信息', '注意事项', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
INSERT INTO `knowledge_doc` VALUES (8, '灵山胜境景区概况与历史渊源', '灵山胜境坐落于江苏省无锡市太湖西北部的马山镇，地处秦履峰、青龙山、白虎山三山环抱之间，占地面积约30万平方米，是国家5A级旅游景区、世界佛教论坛永久会址，被誉为\"东方佛国\"和\"太湖佛国\"。景区的历史可追溯至1300多年前的唐代贞观年间，与玄奘法师西行取经的壮举紧密相连。小灵山的佛教缘起唐贞观年间，玄奘法师西行取经归来，携大乘佛法东传，途经马山时，见此地\"层峦丛翠，曲水净秀，山形酷似印度灵鹫山\"，顿觉此地与佛法渊源深厚，遂将所译《大般若经》中的\"灵鹫胜境\"之名赐予此地，命名为\"小灵山\"，并嘱咐大弟子窥基法师在此住持道场，兴建小灵山庵，奠定了此地的佛教根基。寺院选址颇具禅意：背靠灵山主峰，面朝太湖三万顷碧波，左右青龙白虎二山环抱，形成\"前有照、后有靠、左右有抱\"的风水格局。祥符禅寺的千年兴衰小灵山庵历经数百年发展，至北宋大中祥符年间（1008-1016年），宋真宗赵恒赐额\"祥符禅寺\"，寺院规模不断扩大，成为江南名刹。此后千年间，祥符禅寺历经多次兴废：南宋时曾遭兵燹，元代重建；明代达到鼎盛，香火旺盛；清末民初再次毁于战火，仅存一棵千年银杏、一口六角古井和一段残垣断壁。现代灵山胜境的崛起1994年：\"修复祥符禅寺、建造灵山大佛\"工程奠基，中国佛教协会会长赵朴初提出\"五方五佛\"之论，认为东方空缺，正待填补1997年11月15日：灵山大佛落成开光，成为景区标志性建筑，一期工程完成2003年：二期工程建成开放，以九龙灌浴为主体，完成了佛祖四相成道的轴线布局2006-2009年：三期主体工程完工，包括灵山梵宫、五印坛城、曼飞龙塔等，其中灵山梵宫于2009年1月1日正式开放2009年后：三期辅助工程陆续建成，涵盖灵山精舍、灵山佛学院、三圣殿、慈恩塔等，形成了集信仰、艺术、文化、旅游于一体的综合性佛教文化景区', '景区介绍', '景区概况、历史沿革', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
INSERT INTO `knowledge_doc` VALUES (9, '灵山胜境核心文化内涵', '核心文化内涵：佛教传承与艺术融合的典范佛教文化的深度传承灵山胜境以\"小灵山\"佛教渊源为根基，融合了汉传佛教与藏传佛教文化精髓，形成了独特的佛教文化体系。景区内的祥符禅寺作为千年古刹，保留了古井、银杏等历史遗存，见证了佛教在此地的千年传承。灵山大佛的建造则体现了赵朴初\"五方五佛\"的理念，与香港天坛大佛、四川乐山大佛、山西云冈大佛、河南龙门大佛共同构成了中国佛教的五大佛像格局，象征着佛教文化在中国的广泛传播。传统艺术与现代科技的完美融合灵山胜境将传统佛教艺术与现代建筑技术、数字科技完美结合，创造了当代佛教艺术的巅峰之作。灵山梵宫被誉为\"佛教艺术的卢浮宫\"，融合了菩提伽耶塔风格与中国石窟艺术，内部汇集了东阳木雕、敦煌壁画、扬州漆器、景泰蓝须弥灯、寿山石雕、景德镇青花斗彩缸等多种传统工艺，同时运用了光学、声学、力学等现代科技，打造出沉浸式的佛教文化体验。祈福文化的特色体验景区内的\"九龙灌浴\"\"天下第一掌\"\"抱佛脚\"等体验项目，成为游客祈福纳祥的重要方式，体现了佛教文化中\"慈悲喜舍\"的精神内核。这些体验项目将佛教仪式转化为游客可参与的互动活动，让游客在参与中感受佛教文化的庄严与神圣，实现了\"感悟灵山，吉祥平安\"的文化理念。世界佛教文化的交流平台灵山胜境作为世界佛教论坛永久会址，已成功举办多届世界佛教论坛，成为全球佛教徒交流的重要平台。景区内的灵山梵宫圣坛可容纳千人，成为佛教文化交流、学术研讨和艺术展示的重要场所，促进了不同佛教流派、不同文化背景之间的对话与融合。', '景区介绍', '文化内涵、佛教文化', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
INSERT INTO `knowledge_doc` VALUES (10, '灵山胜境核心景点详解', '灵山大佛：世界最高露天青铜释迦牟尼立像项目详细信息基本数据通高88米（佛体79米，莲花瓣9米），总高101.5米，总用铜量725吨，佛体由1560块6-8毫米厚的铜壁板构成，焊缝总长度逾35公里，相当于一个半足球场大小的铜壁板面积建造工艺采用现代高科技与传统工艺相结合的方式，历经3年工期（1994-1997年），经过钢筋混凝土结构浇制、钢支架安装、铜片拼装焊接、整体抛光着色等阶段佛教意义右手施无畏印（除却众生痛苦），左手施与愿印（赐予众生欢乐），216级登云道暗合佛教108烦恼与108愿望，分为两段，前段108级为\"烦恼尽除\"，后段108级为\"愿望圆满\"最佳体验登顶抱佛脚，俯瞰太湖全景，感受大佛宏伟气势；在不同角度拍摄大佛，尤其是在夕阳西下时，金色阳光洒在大佛身上，佛光普照，美不胜收灵山梵宫：佛教艺术的卢浮宫项目详细信息建筑规模建筑面积7.2万平方米，造价18亿，外观以华藏塔风格为主，融合了石窟与传统佛教建筑元素，顶部五座莲花圣塔象征\"五方五佛\"核心艺术- 穹顶天象图：28米高星空穹顶，用100公斤纯金绘制，148尊飞天姿态各异，依据唐代不空法师所译《佛说炽盛光大威德消灾吉祥陀罗尼经》创作- 华藏世界琉璃壁画：160块琉璃构件，2000吨琉璃熔铸，翡翠镶嵌的菩提叶脉络在特定角度会显现般若经文，堪称当代佛教艺术巅峰之作- 东阳木雕群：以贵重金丝楠木为主材，通过精湛东阳木雕手法，展现花卉、云纹、四灵、回型等元素特色体验欣赏内部艺术装饰，体验佛教文化氛围；观看《吉祥颂》演出（每日10:35、11:30、14:00、16:00，时长20分钟），圣坛内设全球唯一大型旋转舞台，运用全息投影、水雾等技术，演绎佛陀修行成佛的故事文化地位世界佛教论坛主会场，成为全球佛教文化交流的重要场所，展现了中国佛教文化的现代传承与创新九龙灌浴：佛陀诞生的神圣再现项目详细信息基本数据总高27.5米，青铜重量260吨，中央为7.2米高鎏金太子佛像，立于莲花座上表演内容每日4-5场表演，莲花瓣缓缓开启，太子佛像在九龙喷泉与《佛诞颂》音乐中旋转升起，九龙吐水为太子沐浴，水幕与阳光交织出七彩佛光，展现\"花开见佛\"的神圣瞬间佛教意义再现释迦牟尼诞生时\"九龙吐水\"的经典场景，佛陀诞生时一手指天，一手指地，说：\"天上天下，唯我独尊\"特色体验表演结束后可接取祈福圣水，寓意吉祥安康；在不同角度拍摄表演过程，尤其是在阳光明媚时，彩虹与佛光交织，美不胜收五印坛城：藏传佛教文化的瑰宝项目详细信息建筑风格占地面积约5000平方米，藏传佛教风格建筑，金顶红墙，经幡飘扬，四周围绕一片宁静清澄的香水海内部艺术坛城内供奉五方五佛，中央为毗卢遮那佛；四楼供奉五佛之首——中央佛大日如来；壁画采用纯手工绘制，面积达1500平方米，由中央曼茶罗、金刚界曼茶罗、胎藏界曼茶罗三部分组成佛教意义展现藏传佛教文化艺术精髓，转经廊内设有转经筒，游客可亲手转动经筒，感受\"转经一圈，福慧双增\"的寓意最佳体验体验藏传佛教文化，欣赏独特建筑风格；在外面的平台上，顺时针右绕一或三圈，体验\"绕坛城\"的自在、净心，同时一览灵山胜境的全貌祥符禅寺：千年古刹的历史遗存项目详细信息历史遗存- 千年银杏：树龄逾千年，枝繁叶茂，秋季金黄一片，是祥符禅寺历史的见证- 六角井与八角井：两口神话色彩的古井，水质甘甜，传说为\"八功德水\"，有治病健身之效- 江南第一钟：重达12.8吨，钟声悠扬，响彻太湖之滨佛教活动撞钟祈福：游客可参与撞钟活动，钟声象征着\"烦恼尽除，福慧增长\"，体验佛教文化的庄严与神圣文化地位作为小灵山佛教文化的发源地，祥符禅寺是连接历史与现代的重要纽带，展现了佛教文化在中国的千年传承其他特色景点佛手广场：\"天下第一掌\"为灵山大佛右手复制，高11.7米，宽5.5米，摸掌祈福，寓意\"沾福气、保平安\"，与\"抱佛脚\"并称灵山两大祈福体验百子戏弥勒：大型青铜雕塑，弥勒佛笑容可掬，周围百个孩童形态各异，体现佛教\"皆大欢喜\"理念，展现生活百态，充满童趣与欢乐氛围曼飞龙塔：傣族佛教建筑风格，园林景观设计理念，与自然环境和谐融合，展现了不同民族佛教文化的特色灵山精舍：禅意酒店，含素斋与早课体验，适合深度感受佛教文化，体验\"天人合一\"的传统园林文化思想', '景区介绍', '核心景点、景点详情', '2026-04-17 18:19:57', '2026-04-17 18:19:57');
